using UnityEditor;
public static class CountTex {
  public static string Run() {
    var guids = AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Bundle/Role" });
    int sprite = 0, other = 0;
    string sample = "";
    foreach (var g in guids) {
      string p = AssetDatabase.GUIDToAssetPath(g);
      var imp = AssetImporter.GetAtPath(p) as TextureImporter;
      if (imp == null) { other++; continue; }
      if (imp.textureType == TextureImporterType.Sprite) sprite++; else { other++; if (sample.Length < 200) sample += p + ":" + imp.textureType + "; "; }
    }
    return "n=" + guids.Length + " sprite=" + sprite + " other=" + other + " " + sample;
  }
}
